ALTER POLICY "Users can create acquisitions" ON public.project_acquisitions WITH CHECK (contribution_id IS NULL AND EXISTS (SELECT 1 FROM projects p WHERE p.id = project_acquisitions.project_id AND ((p.team_id IS NOT NULL AND is_team_admin(p.team_id)) OR (p.team_id IS NULL AND p.created_by = auth.uid()))));
ALTER POLICY "Users can update acquisitions" ON public.project_acquisitions USING (contribution_id IS NULL AND EXISTS (SELECT 1 FROM projects p WHERE p.id = project_acquisitions.project_id AND ((p.team_id IS NOT NULL AND is_team_admin(p.team_id)) OR (p.team_id IS NULL AND p.created_by = auth.uid()))));
